16	IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY
17	FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
18	AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
19	LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
20	OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN
21	THE SOFTWARE.
22	
23	*/
24	
25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * ARP ethernet frame receiver (Ethernet frame in, ARP frame out)
33	 */
34	module arp_eth_rx #
35	(
36	    // Width of AXI stream interfaces in bits
37	    parameter DATA_WIDTH = 8,
38	    // Propagate tkeep signal
39	    // If disabled, tkeep assumed to be 1'b1
40	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
41	    // tkeep signal width (words per cycle)
42	    parameter KEEP_WIDTH = (DATA_WIDTH/8)
43	)
44	(
45	    input  wire                   clk,
46	    input  wire                   rst,
47	
48	    /*
49	     * Ethernet frame input
50	     */
51	    input  wire                   s_eth_hdr_valid,
52	    output wire                   s_eth_hdr_ready,
53	    input  wire [47:0]            s_eth_dest_mac,
54	    input  wire [47:0]            s_eth_src_mac,
55	    input  wire [15:0]            s_eth_type,
56	    input  wire [DATA_WIDTH-1:0]  s_eth_payload_axis_tdata,
57	    input  wire [KEEP_WIDTH-1:0]  s_eth_payload_axis_tkeep,
58	    input  wire                   s_eth_payload_axis_tvalid,
59	    output wire                   s_eth_payload_axis_tready,
60	    input  wire                   s_eth_payload_axis_tlast,
61	    input  wire                   s_eth_payload_axis_tuser,
62	
63	    /*
64	     * ARP frame output
65	     */
66	    output wire                   m_frame_valid,
67	    input  wire                   m_frame_ready,
68	    output wire [47:0]            m_eth_dest_mac,
69	    output wire [47:0]            m_eth_src_mac,
70	    output wire [15:0]            m_eth_type,
71	    output wire [15:0]            m_arp_htype,
72	    output wire [15:0]            m_arp_ptype,
73	    output wire [7:0]             m_arp_hlen,
74	    output wire [7:0]             m_arp_plen,
75	    output wire [15:0]            m_arp_oper,
76	    output wire [47:0]            m_arp_sha,
77	    output wire [31:0]            m_arp_spa,
78	    output wire [47:0]            m_arp_tha,
79	    output wire [31:0]            m_arp_tpa,
80	
81	    /*
82	     * Status signals
83	     */
84	    output wire                   busy,
85	    output wire                   error_header_early_termination,
86	    output wire                   error_invalid_header
87	);
88	
89	parameter BYTE_LANES = KEEP_ENABLE ? KEEP_WIDTH : 1;
90	
91	parameter HDR_SIZE = 28;
92	
93	parameter CYCLE_COUNT = (HDR_SIZE+BYTE_LANES-1)/BYTE_LANES;
94	
95	parameter PTR_WIDTH = $clog2(CYCLE_COUNT);
96	
97	parameter OFFSET = HDR_SIZE % BYTE_LANES;
98	
99	// bus width assertions
100	initial begin
101	    if (BYTE_LANES * 8 != DATA_WIDTH) begin
102	        $error("Error: AXI stream interface requires byte (8-bit) granularity (instance %m)");
103	        $finish;
104	    end
105	end
106	
107	/*
108	
109	ARP Frame
110	
111	 Field                       Length
112	 Destination MAC address     6 octets
113	 Source MAC address          6 octets
114	 Ethertype (0x0806)          2 octets
115	 HTYPE (1)                   2 octets
116	 PTYPE (0x0800)              2 octets
117	 HLEN (6)                    1 octets
118	 PLEN (4)                    1 octets
119	 OPER                        2 octets
120	 SHA Sender MAC              6 octets
121	 SPA Sender IP               4 octets
122	 THA Target MAC              6 octets
123	 TPA Target IP               4 octets
124	
125	This module receives an Ethernet frame with header fields in parallel and
126	payload on an AXI stream interface, decodes the ARP packet fields, and
127	produces the frame fields in parallel.  
128	
129	*/
130	
131	// datapath control signals
132	reg store_eth_hdr;
133	
134	reg read_eth_header_reg = 1'b1, read_eth_header_next;
135	reg read_arp_header_reg = 1'b0, read_arp_header_next;
136	reg [PTR_WIDTH-1:0] ptr_reg = 0, ptr_next;
137	
138	reg s_eth_hdr_ready_reg = 1'b0, s_eth_hdr_ready_next;
139	reg s_eth_payload_axis_tready_reg = 1'b0, s_eth_payload_axis_tready_next;
140	
141	reg m_frame_valid_reg = 1'b0, m_frame_valid_next;
142	reg [47:0] m_eth_dest_mac_reg = 48'd0;
143	reg [47:0] m_eth_src_mac_reg = 48'd0;
144	reg [15:0] m_eth_type_reg = 16'd0;
145	reg [15:0] m_arp_htype_reg = 16'd0, m_arp_htype_next;
146	reg [15:0] m_arp_ptype_reg = 16'd0, m_arp_ptype_next;
147	reg [7:0]  m_arp_hlen_reg = 8'd0, m_arp_hlen_next;
148	reg [7:0]  m_arp_plen_reg = 8'd0, m_arp_plen_next;
149	reg [15:0] m_arp_oper_reg = 16'd0, m_arp_oper_next;
150	reg [47:0] m_arp_sha_reg = 48'd0, m_arp_sha_next;
151	reg [31:0] m_arp_spa_reg = 32'd0, m_arp_spa_next;
152	reg [47:0] m_arp_tha_reg = 48'd0, m_arp_tha_next;
153	reg [31:0] m_arp_tpa_reg = 32'd0, m_arp_tpa_next;
154	
155	reg busy_reg = 1'b0;
156	reg error_header_early_termination_reg = 1'b0, error_header_early_termination_next;
157	reg error_invalid_header_reg = 1'b0, error_invalid_header_next;
158	
159	assign s_eth_hdr_ready = s_eth_hdr_ready_reg;
160	assign s_eth_payload_axis_tready = s_eth_payload_axis_tready_reg;
161	
162	assign m_frame_valid = m_frame_valid_reg;
163	assign m_eth_dest_mac = m_eth_dest_mac_reg;
164	assign m_eth_src_mac = m_eth_src_mac_reg;
165	assign m_eth_type = m_eth_type_reg;
166	assign m_arp_htype = m_arp_htype_reg;
167	assign m_arp_ptype = m_arp_ptype_reg;
168	assign m_arp_hlen = m_arp_hlen_reg;
169	assign m_arp_plen = m_arp_plen_reg;
170	assign m_arp_oper = m_arp_oper_reg;
171	assign m_arp_sha = m_arp_sha_reg;
172	assign m_arp_spa = m_arp_spa_reg;
173	assign m_arp_tha = m_arp_tha_reg;
174	assign m_arp_tpa = m_arp_tpa_reg;
175	
176	assign busy = busy_reg;
177	assign error_header_early_termination = error_header_early_termination_reg;
178	assign error_invalid_header = error_invalid_header_reg;
179	
180	always @* begin
181	    read_eth_header_next = read_eth_header_reg;
182	    read_arp_header_next = read_arp_header_reg;
183	    ptr_next = ptr_reg;
184	
185	    s_eth_hdr_ready_next = 1'b0;
186	    s_eth_payload_axis_tready_next = 1'b0;
187	
188	    store_eth_hdr = 1'b0;
189	
190	    m_frame_valid_next = m_frame_valid_reg && !m_frame_ready;
191	
192	    m_arp_htype_next = m_arp_htype_reg;
193	    m_arp_ptype_next = m_arp_ptype_reg;
194	    m_arp_hlen_next = m_arp_hlen_reg;
195	    m_arp_plen_next = m_arp_plen_reg;
196	    m_arp_oper_next = m_arp_oper_reg;
197	    m_arp_sha_next = m_arp_sha_reg;
198	    m_arp_spa_next = m_arp_spa_reg;
199	    m_arp_tha_next = m_arp_tha_reg;
200	    m_arp_tpa_next = m_arp_tpa_reg;
201	
202	    error_header_early_termination_next = 1'b0;
203	    error_invalid_header_next = 1'b0;
204	
205	    if (s_eth_hdr_ready && s_eth_hdr_valid) begin
206	        if (read_eth_header_reg) begin
207	            store_eth_hdr = 1'b1;
208	            ptr_next = 0;
209	            read_eth_header_next = 1'b0;
210	            read_arp_header_next = 1'b1;
211	        end
212	    end
213	
214	    if (s_eth_payload_axis_tready && s_eth_payload_axis_tvalid) begin
215	        if (read_arp_header_reg) begin
216	            // word transfer in - store it
217	            ptr_next = ptr_reg + 1;
218	
219	            `define _HEADER_FIELD_(offset, field) \
220	                if (ptr_reg == offset/BYTE_LANES && (!KEEP_ENABLE || s_eth_payload_axis_tkeep[offset%BYTE_LANES])) begin \
221	                    field = s_eth_payload_axis_tdata[(offset%BYTE_LANES)*8 +: 8]; \
222	                end
223	
224	            `_HEADER_FIELD_(0,  m_arp_htype_next[1*8 +: 8])
225	            `_HEADER_FIELD_(1,  m_arp_htype_next[0*8 +: 8])
226	            `_HEADER_FIELD_(2,  m_arp_ptype_next[1*8 +: 8])
227	            `_HEADER_FIELD_(3,  m_arp_ptype_next[0*8 +: 8])
228	            `_HEADER_FIELD_(4,  m_arp_hlen_next[0*8 +: 8])
229	            `_HEADER_FIELD_(5,  m_arp_plen_next[0*8 +: 8])
230	            `_HEADER_FIELD_(6,  m_arp_oper_next[1*8 +: 8])
231	            `_HEADER_FIELD_(7,  m_arp_oper_next[0*8 +: 8])
232	            `_HEADER_FIELD_(8,  m_arp_sha_next[5*8 +: 8])
233	            `_HEADER_FIELD_(9,  m_arp_sha_next[4*8 +: 8])
234	            `_HEADER_FIELD_(10, m_arp_sha_next[3*8 +: 8])
235	            `_HEADER_FIELD_(11, m_arp_sha_next[2*8 +: 8])
236	            `_HEADER_FIELD_(12, m_arp_sha_next[1*8 +: 8])
237	            `_HEADER_FIELD_(13, m_arp_sha_next[0*8 +: 8])
238	            `_HEADER_FIELD_(14, m_arp_spa_next[3*8 +: 8])
239	            `_HEADER_FIELD_(15, m_arp_spa_next[2*8 +: 8])
240	            `_HEADER_FIELD_(16, m_arp_spa_next[1*8 +: 8])
241	            `_HEADER_FIELD_(17, m_arp_spa_next[0*8 +: 8])
242	            `_HEADER_FIELD_(18, m_arp_tha_next[5*8 +: 8])
243	            `_HEADER_FIELD_(19, m_arp_tha_next[4*8 +: 8])
244	            `_HEADER_FIELD_(20, m_arp_tha_next[3*8 +: 8])
245	            `_HEADER_FIELD_(21, m_arp_tha_next[2*8 +: 8])
246	            `_HEADER_FIELD_(22, m_arp_tha_next[1*8 +: 8])
247	            `_HEADER_FIELD_(23, m_arp_tha_next[0*8 +: 8])
248	            `_HEADER_FIELD_(24, m_arp_tpa_next[3*8 +: 8])
249	            `_HEADER_FIELD_(25, m_arp_tpa_next[2*8 +: 8])
250	            `_HEADER_FIELD_(26, m_arp_tpa_next[1*8 +: 8])
251	            `_HEADER_FIELD_(27, m_arp_tpa_next[0*8 +: 8])
252	
253	            if (ptr_reg == 27/BYTE_LANES && (!KEEP_ENABLE || s_eth_payload_axis_tkeep[27%BYTE_LANES])) begin
254	                read_arp_header_next = 1'b0;
255	            end
256	
257	            `undef _HEADER_FIELD_
258	        end
259	
260	        if (s_eth_payload_axis_tlast) begin
261	            if (read_arp_header_next) begin
262	                // don't have the whole header
263	                error_header_early_termination_next = 1'b1;
264	            end else if (m_arp_hlen_next != 4'd6 || m_arp_plen_next != 4'd4) begin
265	                // lengths not valid
266	                error_invalid_header_next = 1'b1;
267	            end else begin
268	                // otherwise, transfer tuser
269	                m_frame_valid_next = !s_eth_payload_axis_tuser;
270	            end
271	
272	            ptr_next = 1'b0;
273	            read_eth_header_next = 1'b1;
274	            read_arp_header_next = 1'b0;
275	        end
276	    end
277	
278	    if (read_eth_header_next) begin
279	        s_eth_hdr_ready_next = !m_frame_valid_next;
280	    end else begin
281	        s_eth_payload_axis_tready_next = 1'b1;
282	    end
283	end
284	
285	always @(posedge clk) begin
286	    read_eth_header_reg <= read_eth_header_next;
287	    read_arp_header_reg <= read_arp_header_next;
288	    ptr_reg <= ptr_next;
289	
290	    s_eth_hdr_ready_reg <= s_eth_hdr_ready_next;
291	    s_eth_payload_axis_tready_reg <= s_eth_payload_axis_tready_next;
292	
293	    m_frame_valid_reg <= m_frame_valid_next;
294	
295	    m_arp_htype_reg <= m_arp_htype_next;
296	    m_arp_ptype_reg <= m_arp_ptype_next;
297	    m_arp_hlen_reg <= m_arp_hlen_next;
298	    m_arp_plen_reg <= m_arp_plen_next;
299	    m_arp_oper_reg <= m_arp_oper_next;
300	    m_arp_sha_reg <= m_arp_sha_next;
301	    m_arp_spa_reg <= m_arp_spa_next;
302	    m_arp_tha_reg <= m_arp_tha_next;
303	    m_arp_tpa_reg <= m_arp_tpa_next;
304	
305	    error_header_early_termination_reg <= error_header_early_termination_next;
306	    error_invalid_header_reg <= error_invalid_header_next;
307	
308	    busy_reg <= read_arp_header_next;
309	
310	    // datapath
311	    if (store_eth_hdr) begin
312	        m_eth_dest_mac_reg <= s_eth_dest_mac;
313	        m_eth_src_mac_reg <= s_eth_src_mac;
314	        m_eth_type_reg <= s_eth_type;
315	    end
316	
317	    if (rst) begin
318	        read_eth_header_reg <= 1'b1;
319	        read_arp_header_reg <= 1'b0;
320	        ptr_reg <= 0;
321	        s_eth_payload_axis_tready_reg <= 1'b0;
322	        m_frame_valid_reg <= 1'b0;
323	        busy_reg <= 1'b0;
324	        error_header_early_termination_reg <= 1'b0;
325	        error_invalid_header_reg <= 1'b0;
326	    end 
327	end
328	
329	endmodule
330	
331	`resetall
332

