25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * ARP ethernet frame transmitter (ARP frame in, Ethernet frame out)
33	 */
34	module arp_eth_tx #
35	(
36	    // Width of AXI stream interfaces in bits
37	    parameter DATA_WIDTH = 8,
38	    // Propagate tkeep signal
39	    // If disabled, tkeep assumed to be 1'b1
40	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
41	    // tkeep signal width (words per cycle)
42	    parameter KEEP_WIDTH = (DATA_WIDTH/8)
43	)
44	(
45	    input  wire                   clk,
46	    input  wire                   rst,
47	
48	    /*
49	     * ARP frame input
50	     */
51	    input  wire                   s_frame_valid,
52	    output wire                   s_frame_ready,
53	    input  wire [47:0]            s_eth_dest_mac,
54	    input  wire [47:0]            s_eth_src_mac,
55	    input  wire [15:0]            s_eth_type,
56	    input  wire [15:0]            s_arp_htype,
57	    input  wire [15:0]            s_arp_ptype,
58	    input  wire [15:0]            s_arp_oper,
59	    input  wire [47:0]            s_arp_sha,
60	    input  wire [31:0]            s_arp_spa,
61	    input  wire [47:0]            s_arp_tha,
62	    input  wire [31:0]            s_arp_tpa,
63	
64	    /*
65	     * Ethernet frame output
66	     */
67	    output wire                   m_eth_hdr_valid,
68	    input  wire                   m_eth_hdr_ready,
69	    output wire [47:0]            m_eth_dest_mac,
70	    output wire [47:0]            m_eth_src_mac,
71	    output wire [15:0]            m_eth_type,
72	    output wire [DATA_WIDTH-1:0]  m_eth_payload_axis_tdata,
73	    output wire [KEEP_WIDTH-1:0]  m_eth_payload_axis_tkeep,
74	    output wire                   m_eth_payload_axis_tvalid,
75	    input  wire                   m_eth_payload_axis_tready,
76	    output wire                   m_eth_payload_axis_tlast,
77	    output wire                   m_eth_payload_axis_tuser,
78	
79	    /*
80	     * Status signals
81	     */
82	    output wire                   busy
83	);
84	
85	parameter BYTE_LANES = KEEP_ENABLE ? KEEP_WIDTH : 1;
86	
87	parameter HDR_SIZE = 28;
88	
89	parameter CYCLE_COUNT = (HDR_SIZE+BYTE_LANES-1)/BYTE_LANES;
90	
91	parameter PTR_WIDTH = $clog2(CYCLE_COUNT);
92	
93	parameter OFFSET = HDR_SIZE % BYTE_LANES;
94	
95	// bus width assertions
96	initial begin
97	    if (BYTE_LANES * 8 != DATA_WIDTH) begin
98	        $error("Error: AXI stream interface requires byte (8-bit) granularity (instance %m)");
99	        $finish;
100	    end
101	end
102	
103	/*
104	
105	ARP Frame
106	
107	 Field                       Length
108	 Destination MAC address     6 octets
109	 Source MAC address          6 octets
110	 Ethertype (0x0806)          2 octets
111	 HTYPE (1)                   2 octets
112	 PTYPE (0x0800)              2 octets
113	 HLEN (6)                    1 octets
114	 PLEN (4)                    1 octets
115	 OPER                        2 octets
116	 SHA Sender MAC              6 octets
117	 SPA Sender IP               4 octets
118	 THA Target MAC              6 octets
119	 TPA Target IP               4 octets
120	
121	This module receives an ARP frame with header fields in parallel  and
122	transmits the complete Ethernet payload on an AXI interface.
123	
124	*/
125	
126	// datapath control signals
127	reg store_frame;
128	
129	reg send_arp_header_reg = 1'b0, send_arp_header_next;
130	reg [PTR_WIDTH-1:0] ptr_reg = 0, ptr_next;
131	
132	reg [15:0] arp_htype_reg = 16'd0;
133	reg [15:0] arp_ptype_reg = 16'd0;
134	reg [15:0] arp_oper_reg = 16'd0;
135	reg [47:0] arp_sha_reg = 48'd0;
136	reg [31:0] arp_spa_reg = 32'd0;
137	reg [47:0] arp_tha_reg = 48'd0;
138	reg [31:0] arp_tpa_reg = 32'd0;
139	
140	reg s_frame_ready_reg = 1'b0, s_frame_ready_next;
141	
142	reg m_eth_hdr_valid_reg = 1'b0, m_eth_hdr_valid_next;
143	reg [47:0] m_eth_dest_mac_reg = 48'd0;
144	reg [47:0] m_eth_src_mac_reg = 48'd0;
145	reg [15:0] m_eth_type_reg = 16'd0;
146	
147	reg busy_reg = 1'b0;
148	
149	// internal datapath
150	reg [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_int;
151	reg [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_int;
152	reg                  m_eth_payload_axis_tvalid_int;
153	reg                  m_eth_payload_axis_tready_int_reg = 1'b0;
154	reg                  m_eth_payload_axis_tlast_int;
155	reg                  m_eth_payload_axis_tuser_int;
156	wire                 m_eth_payload_axis_tready_int_early;
157	
158	assign s_frame_ready = s_frame_ready_reg;
159	
160	assign m_eth_hdr_valid = m_eth_hdr_valid_reg;
161	assign m_eth_dest_mac = m_eth_dest_mac_reg;
162	assign m_eth_src_mac = m_eth_src_mac_reg;
163	assign m_eth_type = m_eth_type_reg;
164	
165	assign busy = busy_reg;
166	
167	always @* begin
168	    send_arp_header_next = send_arp_header_reg;
169	    ptr_next = ptr_reg;
170	
171	    s_frame_ready_next = 1'b0;
172	
173	    store_frame = 1'b0;
174	
175	    m_eth_hdr_valid_next = m_eth_hdr_valid_reg && !m_eth_hdr_ready;
176	
177	    m_eth_payload_axis_tdata_int = {DATA_WIDTH{1'b0}};
178	    m_eth_payload_axis_tkeep_int = {KEEP_WIDTH{1'b0}};
179	    m_eth_payload_axis_tvalid_int = 1'b0;
180	    m_eth_payload_axis_tlast_int = 1'b0;
181	    m_eth_payload_axis_tuser_int = 1'b0;
182	
183	    if (s_frame_ready && s_frame_valid) begin
184	        store_frame = 1'b1;
185	        m_eth_hdr_valid_next = 1'b1;
186	        ptr_next = 0;
187	        send_arp_header_next = 1'b1;
188	    end
189	
190	    if (m_eth_payload_axis_tready_int_reg) begin
191	        if (send_arp_header_reg) begin
192	            ptr_next = ptr_reg + 1;
193	
194	            m_eth_payload_axis_tdata_int = {DATA_WIDTH{1'b0}};
195	            m_eth_payload_axis_tkeep_int = {KEEP_WIDTH{1'b0}};
196	            m_eth_payload_axis_tvalid_int = 1'b1;
197	            m_eth_payload_axis_tlast_int = 1'b0;
198	            m_eth_payload_axis_tuser_int = 1'b0;
199	
200	            `define _HEADER_FIELD_(offset, field) \
201	                if (ptr_reg == offset/BYTE_LANES) begin \
202	                    m_eth_payload_axis_tdata_int[(offset%BYTE_LANES)*8 +: 8] = field; \
203	                    m_eth_payload_axis_tkeep_int[offset%BYTE_LANES] = 1'b1; \
204	                end
205	
206	            `_HEADER_FIELD_(0,  arp_htype_reg[1*8 +: 8])
207	            `_HEADER_FIELD_(1,  arp_htype_reg[0*8 +: 8])
208	            `_HEADER_FIELD_(2,  arp_ptype_reg[1*8 +: 8])
209	            `_HEADER_FIELD_(3,  arp_ptype_reg[0*8 +: 8])
210	            `_HEADER_FIELD_(4,  8'd6)
211	            `_HEADER_FIELD_(5,  8'd4)
212	            `_HEADER_FIELD_(6,  arp_oper_reg[1*8 +: 8])
213	            `_HEADER_FIELD_(7,  arp_oper_reg[0*8 +: 8])
214	            `_HEADER_FIELD_(8,  arp_sha_reg[5*8 +: 8])
215	            `_HEADER_FIELD_(9,  arp_sha_reg[4*8 +: 8])
216	            `_HEADER_FIELD_(10, arp_sha_reg[3*8 +: 8])
217	            `_HEADER_FIELD_(11, arp_sha_reg[2*8 +: 8])
218	            `_HEADER_FIELD_(12, arp_sha_reg[1*8 +: 8])
219	            `_HEADER_FIELD_(13, arp_sha_reg[0*8 +: 8])
220	            `_HEADER_FIELD_(14, arp_spa_reg[3*8 +: 8])
221	            `_HEADER_FIELD_(15, arp_spa_reg[2*8 +: 8])
222	            `_HEADER_FIELD_(16, arp_spa_reg[1*8 +: 8])
223	            `_HEADER_FIELD_(17, arp_spa_reg[0*8 +: 8])
224	            `_HEADER_FIELD_(18, arp_tha_reg[5*8 +: 8])
225	            `_HEADER_FIELD_(19, arp_tha_reg[4*8 +: 8])
226	            `_HEADER_FIELD_(20, arp_tha_reg[3*8 +: 8])
227	            `_HEADER_FIELD_(21, arp_tha_reg[2*8 +: 8])
228	            `_HEADER_FIELD_(22, arp_tha_reg[1*8 +: 8])
229	            `_HEADER_FIELD_(23, arp_tha_reg[0*8 +: 8])
230	            `_HEADER_FIELD_(24, arp_tpa_reg[3*8 +: 8])
231	            `_HEADER_FIELD_(25, arp_tpa_reg[2*8 +: 8])
232	            `_HEADER_FIELD_(26, arp_tpa_reg[1*8 +: 8])
233	            `_HEADER_FIELD_(27, arp_tpa_reg[0*8 +: 8])
234	
235	            if (ptr_reg == 27/BYTE_LANES) begin
236	                m_eth_payload_axis_tlast_int = 1'b1;
237	                send_arp_header_next = 1'b0;
238	            end
239	
240	            `undef _HEADER_FIELD_
241	        end
242	    end
243	
244	    s_frame_ready_next = !m_eth_hdr_valid_next && !send_arp_header_next;
245	end
246	
247	always @(posedge clk) begin
248	    send_arp_header_reg <= send_arp_header_next;
249	    ptr_reg <= ptr_next;
250	
251	    s_frame_ready_reg <= s_frame_ready_next;
252	
253	    m_eth_hdr_valid_reg <= m_eth_hdr_valid_next;
254	
255	    busy_reg <= send_arp_header_next;
256	
257	    if (store_frame) begin
258	        m_eth_dest_mac_reg <= s_eth_dest_mac;
259	        m_eth_src_mac_reg <= s_eth_src_mac;
260	        m_eth_type_reg <= s_eth_type;
261	        arp_htype_reg <= s_arp_htype;
262	        arp_ptype_reg <= s_arp_ptype;
263	        arp_oper_reg <= s_arp_oper;
264	        arp_sha_reg <= s_arp_sha;
265	        arp_spa_reg <= s_arp_spa;
266	        arp_tha_reg <= s_arp_tha;
267	        arp_tpa_reg <= s_arp_tpa;
268	    end
269	
270	    if (rst) begin
271	        send_arp_header_reg <= 1'b0;
272	        ptr_reg <= 0;
273	        s_frame_ready_reg <= 1'b0;
274	        m_eth_hdr_valid_reg <= 1'b0;
275	        busy_reg <= 1'b0;
276	    end
277	end
278	
279	// output datapath logic
280	reg [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_reg = {DATA_WIDTH{1'b0}};
281	reg [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_reg = {KEEP_WIDTH{1'b0}};
282	reg                  m_eth_payload_axis_tvalid_reg = 1'b0, m_eth_payload_axis_tvalid_next;
283	reg                  m_eth_payload_axis_tlast_reg = 1'b0;
284	reg                  m_eth_payload_axis_tuser_reg = 1'b0;
285	
286	reg [DATA_WIDTH-1:0] temp_m_eth_payload_axis_tdata_reg = {DATA_WIDTH{1'b0}};
287	reg [KEEP_WIDTH-1:0] temp_m_eth_payload_axis_tkeep_reg = {KEEP_WIDTH{1'b0}};
288	reg                  temp_m_eth_payload_axis_tvalid_reg = 1'b0, temp_m_eth_payload_axis_tvalid_next;
289	reg                  temp_m_eth_payload_axis_tlast_reg = 1'b0;
290	reg                  temp_m_eth_payload_axis_tuser_reg = 1'b0;
291	
292	// datapath control
293	reg store_eth_payload_int_to_output;
294	reg store_eth_payload_int_to_temp;
295	reg store_eth_payload_axis_temp_to_output;
296	
297	assign m_eth_payload_axis_tdata = m_eth_payload_axis_tdata_reg;
298	assign m_eth_payload_axis_tkeep = KEEP_ENABLE ? m_eth_payload_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
299	assign m_eth_payload_axis_tvalid = m_eth_payload_axis_tvalid_reg;
300	assign m_eth_payload_axis_tlast = m_eth_payload_axis_tlast_reg;
301	assign m_eth_payload_axis_tuser = m_eth_payload_axis_tuser_reg;
302	
303	// enable ready input next cycle if output is ready or if both output registers are empty
304	assign m_eth_payload_axis_tready_int_early = m_eth_payload_axis_tready || (!temp_m_eth_payload_axis_tvalid_reg && !m_eth_payload_axis_tvalid_reg);
305	
306	always @* begin
307	    // transfer sink ready state to source
308	    m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_reg;
309	    temp_m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
310	
311	    store_eth_payload_int_to_output = 1'b0;
312	    store_eth_payload_int_to_temp = 1'b0;
313	    store_eth_payload_axis_temp_to_output = 1'b0;
314	
315	    if (m_eth_payload_axis_tready_int_reg) begin
316	        // input is ready
317	        if (m_eth_payload_axis_tready || !m_eth_payload_axis_tvalid_reg) begin
318	            // output is ready or currently not valid, transfer data to output
319	            m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
320	            store_eth_payload_int_to_output = 1'b1;
321	        end else begin
322	            // output is not ready, store input in temp
323	            temp_m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
324	            store_eth_payload_int_to_temp = 1'b1;
325	        end
326	    end else if (m_eth_payload_axis_tready) begin
327	        // input is not ready, but output is ready
328	        m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
329	        temp_m_eth_payload_axis_tvalid_next = 1'b0;
330	        store_eth_payload_axis_temp_to_output = 1'b1;
331	    end
332	end
333	
334	always @(posedge clk) begin
335	    m_eth_payload_axis_tvalid_reg <= m_eth_payload_axis_tvalid_next;
336	    m_eth_payload_axis_tready_int_reg <= m_eth_payload_axis_tready_int_early;
337	    temp_m_eth_payload_axis_tvalid_reg <= temp_m_eth_payload_axis_tvalid_next;
338	
339	    // datapath
340	    if (store_eth_payload_int_to_output) begin
341	        m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
342	        m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
343	        m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
344	        m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
345	    end else if (store_eth_payload_axis_temp_to_output) begin
346	        m_eth_payload_axis_tdata_reg <= temp_m_eth_payload_axis_tdata_reg;
347	        m_eth_payload_axis_tkeep_reg <= temp_m_eth_payload_axis_tkeep_reg;
348	        m_eth_payload_axis_tlast_reg <= temp_m_eth_payload_axis_tlast_reg;
349	        m_eth_payload_axis_tuser_reg <= temp_m_eth_payload_axis_tuser_reg;
350	    end
351	
352	    if (store_eth_payload_int_to_temp) begin
353	        temp_m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
354	        temp_m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
355	        temp_m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
356	        temp_m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
357	    end
358	
359	    if (rst) begin
360	        m_eth_payload_axis_tvalid_reg <= 1'b0;
361	        m_eth_payload_axis_tready_int_reg <= 1'b0;
362	        temp_m_eth_payload_axis_tvalid_reg <= 1'b0;
363	    end
364	end
365	
366	endmodule
367	
368	`resetall
369

